  "The translation appears here": "A tradução aparece aqui",
  "Every part is checked: numbers, names and codes kept exactly.": "Cada parte é conferida: números, nomes e códigos mantidos exatamente.",
  "Open a PDF, Word file, book or web page. Read it here and chat with it — every answer shows the page it came from. Everything stays on your phone.": "Abra um PDF, arquivo Word, livro ou página web. Leia aqui e converse com ele — cada resposta mostra a página de onde veio. Tudo fica no seu celular.",
  "Open a file": "Abrir um arquivo",
  "Reading and searching work now. To chat with the file, install a model in Engine.": "Ler e pesquisar já funcionam. Para conversar com o arquivo, instale um modelo em Motor.",
  "Your documents appear here": "Seus documentos aparecem aqui",
  "Open a file: it is kept on this device, with its chat and notes, so you can come back to it.": "Abra um arquivo: ele fica guardado neste aparelho, com a conversa e as notas, para você voltar a ele.",
  "Stop": "Parar",
  "Describe it in one sentence — the AI on your phone writes a designed PowerPoint or a full report, from the web or your own file. Edit any slide, then save it as PowerPoint, Word or PDF.": "Descreva em uma frase — a IA do seu celular cria um PowerPoint com design ou um relatório completo, a partir da web ou do seu próprio arquivo. Edite qualquer slide e salve como PowerPoint, Word ou PDF.",
  "Presentation": "Apresentação",
  "Report": "Relatório",
  "e.g. A pitch for our café to offices in New Cairo: menu, catering, prices, why us": "ex.: Uma apresentação do nosso café para escritórios no Novo Cairo: cardápio, buffet, preços, por que nós",
  "Research the web for facts and figures": "Pesquisar fatos e números na web",
  "Each slide names its sources, and a Sources slide lists every page": "Cada slide cita suas fontes, e um slide de Fontes lista todas as páginas",
  "Base it on my file (Word, PDF, Excel, CSV…)": "Usar meu arquivo como base (Word, PDF, Excel, CSV…)",
  "Make the presentation": "Criar a apresentação",
  "{n} slides": "{n} slides",
