  "Change": "Trocar",
  "Your slides appear here": "Seus slides aparecem aqui",
  "Each slide or section shows here as it is written.": "Cada slide ou seção aparece aqui conforme é escrito.",
  "Build a CV in English or Arabic, keep a copy for every job, and export a clean PDF or Word file. The AI on your phone helps with wording.": "Monte um currículo em inglês ou árabe, guarde uma cópia para cada vaga e exporte um PDF ou Word caprichado. A IA do seu celular ajuda com o texto.",
  "New CV": "Novo currículo",
  "Import my CV": "Importar meu currículo",
  "No CVs yet": "Nenhum currículo ainda",
  "Start a new one, or import the one you already have.": "Comece um novo ou importe o que você já tem.",
  "Copy a video's link, paste it here, pick the quality — it's saved to your phone's Movies folder. Works with direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons and pages that show a plain video.": "Copie o link de um vídeo, cole aqui, escolha a qualidade — ele é salvo na pasta Filmes do seu celular. Funciona com links diretos de vídeo, Google Drive, Dropbox, archive.org, Wikimedia Commons e páginas que mostram um vídeo simples.",
  "Find the video": "Encontrar o vídeo",
  "The video's versions appear here": "As versões do vídeo aparecem aqui",
  "Paste a link and tap Find the video — then pick the quality to download.": "Cole um link e toque em Encontrar o vídeo — depois escolha a qualidade para baixar.",
  "No map on this device yet": "Ainda não há mapa neste aparelho",
  "Download the world map to see every country, or your country's map for streets, places and offline search.": "Baixe o mapa-múndi para ver todos os países, ou o mapa do seu país para ruas, lugares e busca off-line.",
