  "Code that is tested before you get it": "Código testado antes de chegar a você",
  "The model writes the program and its tests, the phone runs them, and any error goes straight back to the model to fix — until the tests pass. Offline, in a locked sandbox.": "O modelo escreve o programa e os testes, o celular roda tudo, e qualquer erro volta direto para o modelo corrigir — até os testes passarem. Off-line, numa sandbox trancada.",
  "What should it do? e.g. “A function that splits a restaurant bill between friends, with the tip”": "O que deve fazer? ex.: “Uma função que divide a conta do restaurante entre amigos, com a gorjeta”",
