  "= instant filler removal (offline).": "= remoção instantânea de enrolação (off-line).",
  "= the model rewrites it far shorter while keeping the meaning.": "= o modelo reescreve bem mais curto mantendo o sentido.",
  "Result": "Resultado",
  "Paste a wordy prompt and hit": "Cole um prompt prolixo e toque em",
  "— it thinks about meaning, not just filler words.": "— ele pensa no sentido, não só nas palavras de enrolação.",
  "Text to rewrite": "Texto para reescrever",
  "Paste AI-generated or stiff text — it comes back sounding like a person wrote it.": "Cole um texto gerado por IA ou travado — ele volta soando como se uma pessoa tivesse escrito.",
  "Your writing sample": "Sua amostra de escrita",
  "(this is what makes it sound like you)": "(é isso que faz soar como você)",
  "Paste a few paragraphs you wrote yourself — an email, a message, anything in your natural voice.": "Cole alguns parágrafos escritos por você — um e-mail, uma mensagem, qualquer coisa no seu jeito natural.",
  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "Mantém exatamente seu sentido e seus fatos — muda só o jeito de ler. A amostra de escrita é opcional, mas é o que mais faz diferença.",
  "Rewritten": "Reescrito",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "Cole um texto travado ou com cara de IA, adicione uma amostra da sua escrita e ele volta com a sua voz — mesmo sentido, ritmo humano.",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "Converse pelo Attune — ele lê a conversa toda e afia cada próximo prompt.",
  "What do you want out of this whole conversation? (optional, but it makes every prompt better)": "O que você quer tirar desta conversa toda? (opcional, mas melhora cada prompt)",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "Traga a conversa do {t} — cole a conversa inteira ou só a última resposta:",
  "Paste here…": "Cole aqui…",
  "Read it & suggest my reply": "Ler e sugerir minha resposta",
  "What do you want to ask? Type it however you like.": "O que você quer perguntar? Digite do jeito que quiser.",
  "Optimize my prompt": "Otimizar meu prompt",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "O ciclo: digite a intenção → receba um prompt otimizado → envie → traga a resposta de volta → cada próximo prompt fica mais certeiro. No app do celular, o menu Compartilhar substitui totalmente o copiar e colar.",
  "Ready prompt recipes — pick one, fill the blanks, then": "Receitas de prompt prontas — escolha uma, preencha as lacunas e depois",
