  "It answers from this device, and it can look through everything you've asked it before — so questions about your own work have real answers, not guesses.": "Ele responde a partir deste aparelho e pode olhar tudo o que você já perguntou — então perguntas sobre o seu próprio trabalho têm respostas de verdade, não chutes.",
