  "Core Max, Sense, Zenith, Apex and Everest run on a computer: get them in the Attune desktop app.": "Core Max, Sense, Zenith, Apex e Everest rodam num computador: baixe no app Attune para computador.",
  "Too heavy for a phone — it can close the app. Core or Blaze run smoothly here; this one is in the desktop app.": "Pesado demais para um celular — pode fechar o app. Core ou Blaze rodam liso aqui; este fica no app para computador.",
