  "per company system, once": "por sistema de empresa, uma vez",
  "Pro is bought in the Google Play version of Attune — one tap, paid by card or from your Vodafone / Orange / Etisalat balance, and it switches on by itself.": "O Pro é comprado na versão do Attune no Google Play — um toque, pago com cartão ou com o saldo Vodafone / Orange / Etisalat, e ele é ativado sozinho.",
  "Cancel any time in Google Play → Subscriptions. The plan renews by itself; nothing to send, nobody to message.": "Cancele quando quiser em Google Play → Assinaturas. O plano é renovado sozinho; não precisa enviar nada nem mandar mensagem para ninguém.",
