  "Keep anything — a note, a link, a quote, a price, a number, an idea…": "Guarde qualquer coisa — uma nota, um link, uma citação, um preço, um número, uma ideia…",
  "Keep": "Guardar",
  "filing…": "organizando…",
  "Free: keep and search everything. Pro: it files each item by itself (title, summary, tags), reads your photos and answers questions from your Mind.": "Grátis: guarde e pesquise tudo. Pro: organiza cada item sozinho (título, resumo, tags), lê suas fotos e responde perguntas a partir da sua Mente.",
