  "Nothing in your Mind matched — so this is not from your items.": "Nada na sua Mente correspondeu — então esta resposta não vem dos seus itens.",
  "From your past": "Do seu passado",
  "Nothing matches that.": "Nada corresponde a isso.",
  "on this day": "neste dia",
  "a year ago": "há um ano",
  "from your past": "do seu passado",
  "Nothing to read in that.": "Não há nada para ler aí.",
  "That payment did not go through, so there is nothing to record.": "Esse pagamento não foi concluído, então não há nada para registrar.",
  "Sent to Yusr — pick the account and confirm": "Enviado ao Yusr — escolha a conta e confirme",
  "Money isn't bundled in this build.": "O Dinheiro não está incluído nesta versão.",
  "The Yusr document wasn't embedded. On the phone it loads from local assets.": "O documento do Yusr não foi incorporado. No celular, ele carrega dos arquivos do app.",
  "Your ledger and every zakāt ruling live here, unchanged, and free forever. Attune adds memory and plain language on top — it never calculates zakāt and never moves money on its own.": "Seu livro-caixa e todas as regras de zakat ficam aqui, sem mudanças e grátis para sempre. O Attune adiciona memória e linguagem simples por cima — ele nunca calcula a zakat e nunca movimenta dinheiro por conta própria.",
  "Share a payment": "Compartilhar um pagamento",
  "An InstaPay confirmation, a bank SMS, a wallet receipt or a photo of one. Attune reads the amount and who it was, then opens your own transaction sheet with it filled in. You pick the account.": "Uma confirmação do InstaPay, um SMS do banco, um recibo de carteira digital ou a foto de um deles. O Attune lê o valor e para quem foi, e abre a sua própria ficha de transação já preenchida. Você escolhe a conta.",
  "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321": "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321",
  "Read it": "Ler",
  "Reading…": "Lendo…",
  "From a photo": "De uma foto",
  "Three ways, all fine: share the SMS, WhatsApp message or screenshot to Attune from any app (it lands here by itself) · paste it above · or take/pick a photo of the receipt.": "Três jeitos, todos funcionam: compartilhe o SMS, a mensagem do WhatsApp ou o print com o Attune a partir de qualquer app (chega aqui sozinho) · cole acima · ou tire/escolha uma foto do recibo.",
  "read from: “": "lido de: “",
  "· account: you choose, in Yusr": "· conta: você escolhe, no Yusr",
  "Talk to your money": "Converse com seu dinheiro",
  "not saved to memory": "não salvo na memória",
  "saved to memory": "salvo na memória",
  "Answered on this device from the figures Yusr calculated. Ask follow-ups — it keeps the thread. For zakāt it is handed the app's own numbers and forbidden from recomputing them: it explains, it does not rule.": "Respondido neste aparelho a partir dos números que o Yusr calculou. Faça mais perguntas — ele mantém o assunto. Para a zakat, ele recebe os números do próprio app e é proibido de recalculá-los: ele explica, não decide.",
  "figures from Yusr's zakāt engine, not recalculated": "números do cálculo de zakat do Yusr, sem recálculo",
  "ask a follow-up…": "faça outra pergunta…",
  "Thinking…": "Pensando…",
  "What do you make of this?": "O que você acha disso?",
  "Load a model in Engine and this answers with no signal.": "Carregue um modelo no Motor e isto responde mesmo sem sinal.",
  "What stands out": "O que chama a atenção",
  "Every figure here is one Yusr calculated — the model may not produce a new number.": "Todos os números aqui foram calculados pelo Yusr — o modelo não pode criar um número novo.",
  "What the AI is allowed to see": "O que a IA pode ver",
