  "Added to memory": "Adicionado à memória",
  "Only what you confirmed. Attune records nothing on its own.": "Só o que você confirmou. O Attune não registra nada por conta própria.",
  "No signal, so only your saved places are searchable — nothing matched.": "Sem sinal, então só dá para pesquisar seus lugares salvos — nada correspondeu.",
  "Nothing found for that.": "Nada encontrado.",
  "Saved — it works offline now": "Salvo — agora funciona offline",
  "Map tiles cleared": "Mapas guardados apagados",
  "Every area you look at is kept, so it works again with no signal. You can also download an area before you travel. Place search needs a connection; your own saved places are searchable without one.": "Cada área que você olha fica guardada, então funciona de novo sem sinal. Você também pode baixar uma área antes de viajar. A busca de lugares precisa de conexão; seus lugares salvos podem ser pesquisados sem ela.",
  "offline — showing saved tiles": "offline — mostrando mapas guardados",
