  "Translated by the AI on your phone — check important names and numbers.": "Traduzido pela IA do seu celular — confira nomes e números importantes.",
  "Translating needs an AI model — open Engine and install one.": "Para traduzir, é preciso um modelo de IA — abra o Motor e instale um.",
  "The AI on your phone translates it piece by piece; headings, lists, tables and numbers stay in place. Long files take a few minutes.": "A IA do seu celular traduz parte por parte; títulos, listas, tabelas e números ficam no lugar. Arquivos longos levam alguns minutos.",
