  "Long-press the box and choose Paste": "Toque e segure na caixa e escolha Colar",
  "That isn't a link. Copy the video's link (it starts with https://) and paste it here.": "Isso não é um link. Copie o link do vídeo (começa com https://) e cole aqui.",
  "{site} doesn't allow its videos to be downloaded, so Attune can't save them (Google Play removes apps that do). Links that work: direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons, and pages that show a plain video file.": "{site} não permite baixar seus vídeos, então o Attune não pode salvá-los (o Google Play remove apps que fazem isso). Links que funcionam: links diretos de vídeo, Google Drive, Dropbox, archive.org, Wikimedia Commons e páginas que mostram um arquivo de vídeo simples.",
  "a streaming service": "um serviço de streaming",
  "this site": "este site",
  "That's a live-stream link (.m3u8) — it's streamed in pieces and can't be saved as one file.": "Esse é um link de transmissão ao vivo (.m3u8) — ele é transmitido em partes e não pode ser salvo como um único arquivo.",
  "Downloading works in the Android app.": "O download funciona no app Android.",
  "Google Drive didn't give the file — make sure it's shared as \"Anyone with the link\".": "O Google Drive não entregou o arquivo — confira se ele está compartilhado como \"Qualquer pessoa com o link\".",
  "This page plays a {site} video, which can't be downloaded.": "Esta página reproduz um vídeo do {site}, que não pode ser baixado.",
