  ". Entry rules change with no notice and the cost of being wrong is a denied boarding — confirm with the embassy or the official portal before you book.": ". As regras de entrada mudam sem aviso e o preço do erro é ser impedido de embarcar — confirme com a embaixada ou o portal oficial antes de reservar.",
