  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "Ele sabe como as coisas funcionam de verdade aqui — preços justos, cobranças abusivas comuns, o que é falta de educação. Ele avisa quando algo precisa de dados ao vivo que não tem offline.",
