  "This model is large for this phone. It works, but answers come slowly and the phone gets warm. For quick, smooth answers use Qwen 3.5 4B — same Arabic, reads photos, about 3× faster.": "Este modelo é grande para este celular. Funciona, mas as respostas vêm devagar e o celular esquenta. Para respostas rápidas e fluidas, use o Qwen 3.5 4B — mesmo árabe, lê fotos, cerca de 3× mais rápido.",
