  "Installed weights never update on their own, so a prompt that works today works the same way in a year. The fingerprint proves exactly which file is answering.": "Os pesos instalados nunca se atualizam sozinhos, então um prompt que funciona hoje funciona igual daqui a um ano. A impressão digital prova exatamente qual arquivo está respondendo.",
  "Add any model": "Adicionar qualquer modelo",
  "unsloth/Qwen3.5-9B-GGUF:Q4_K_M   or   https://…/model.gguf": "unsloth/Qwen3.5-9B-GGUF:Q4_K_M   ou   https://…/model.gguf",
  "Any GGUF on Hugging Face as": "Qualquer GGUF do Hugging Face como",
  ", or a direct https link. Specialist and fine-tuned models install the same way — the photo reader is fetched too when the repo has one.": ", ou um link https direto. Modelos especializados e ajustados (fine-tuned) são instalados do mesmo jeito — o leitor de fotos também é baixado quando o repositório tem um.",
  "How it answers": "Como ele responde",
  "e.g. I run a small shop in Egypt. Answer in Egyptian Arabic unless I write in English. Give prices in EGP.": "Ex.: Tenho uma loja pequena no Egito. Responda em árabe egípcio, a menos que eu escreva em inglês. Dê os preços em EGP.",
  "Saved when you tap outside the box. Stays on this phone.": "Salvo quando você toca fora da caixa. Fica neste celular.",
  "Web lookup": "Busca na web",
