  "Nothing has left the phone.": "Nada saiu do celular.",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \"nothing leaves this phone\".": "O modelo em si nunca usa a rede. O registro lista cada conexão que o app fez ou recusou, só com o host e o motivo — a prova de que \"nada sai deste celular\".",
