  "INT4 KV cache + sliding-window eviction, so long conversations don't grow unbounded.": "Cache KV INT4 + descarte por janela deslizante, para que conversas longas não cresçam sem limite.",
  "Storage:": "Armazenamento:",
  "Compute": "Processamento",
  "Prefill runs where compute is fastest, decode where bandwidth is. Using both raises usable bandwidth ~43 → 59 GB/s.": "O prefill roda onde o processamento é mais rápido; o decode, onde a largura de banda é maior. Usar os dois eleva a largura de banda útil de ~43 para 59 GB/s.",
  "Task adapters": "Adaptadores de tarefas",
  "Small fine-tunes for each job — this is what makes a phone-sized model punch above its weight. Loaded over the base model, a few MB each.": "Pequenos ajustes (fine-tunes) para cada tarefa — é isso que faz um modelo do tamanho de um celular render acima do esperado. Carregados sobre o modelo base, com alguns MB cada.",
