  "Keep everything on this phone and add the backup's chats, memory, reminders and cycle days. The Money ledger is only taken from the backup if this phone has none.": "Mantém tudo que está neste celular e adiciona as conversas, a memória, os lembretes e os dias de ciclo do backup. O livro de Dinheiro só vem do backup se este celular não tiver nenhum.",
  "This phone's {c} chats and {l} ledger entries will be replaced by the backup's. You can undo this once, right after.": "As {c} conversas e os {l} lançamentos deste celular serão substituídos pelos do backup. Você pode desfazer uma vez, logo depois.",
