  "Name the outcome; it fills in the path.": "Diga o resultado que quer; ele monta o caminho.",
  "Huge window — compress for cost, not for fit.": "Janela enorme — comprima para reduzir custo, não para caber.",
  "Direct phrasing; ask for reasoning explicitly.": "Frases diretas; peça o raciocínio de forma explícita.",
