  "refunds and shared keys": "reembolsos e chaves compartilhadas",
  "Qwen3.6 35B-A3B · long context": "Qwen3.6 35B-A3B · contexto longo",
  "Write": "Escrever",
  "Review": "Revisar",
  "Long documents": "Documentos longos",
  "The strongest dense model that still fits a 32 GB machine. Quantisation-aware trained, so 4-bit costs almost nothing in quality here.": "O modelo denso mais forte que ainda cabe em uma máquina de 32 GB. Treinado com consciência de quantização, então 4 bits quase não custa qualidade aqui.",
  "26B-class answers with under 4B active per token. The best quality-per-second on a strong laptop.": "Respostas de classe 26B com menos de 4B ativos por token. A melhor qualidade por segundo em um notebook potente.",
  "Reads text, images and audio. Comfortable on a laptop or a 16 GB phone.": "Lê texto, imagens e áudio. Confortável em um notebook ou em um celular de 16 GB.",
  "Photos": "Fotos",
  "The strongest sub-10B model measured anywhere, and the best of these at reading documents and photographs.": "O modelo abaixo de 10B mais forte já medido, e o melhor deles para ler documentos e fotografias.",
  "The one to have if your phone can hold it. Reads photographs of documents and receipts, handles Arabic and English, and a fifth bit of precision over the smaller build is a real quality difference you can feel on long answers.": "O ideal se o seu celular aguentar. Lê fotos de documentos e recibos, domina árabe e inglês, e um quinto bit de precisão a mais que a versão menor é uma diferença real de qualidade, que você sente em respostas longas.",
  "Text, images and audio on a flagship phone. Pick this over the Qwen if you want voice notes read back to you.": "Texto, imagens e áudio em um celular topo de linha. Escolha este em vez do Qwen se quiser ouvir suas notas de voz lidas de volta.",
  "Voice": "Voz",
  "The sweet spot on an ordinary modern phone. Everything the app does, in under 3 GB.": "O ponto ideal em um celular moderno comum. Tudo que o app faz, em menos de 3 GB.",
  "The same 4B model squeezed 10% smaller for a 4 GB phone. Slightly slower on older chips, and worth it to get the 4B rather than dropping to the 2B.": "O mesmo modelo 4B, 10% menor, para um celular de 4 GB. Um pouco mais lento em chips antigos, e vale a pena para ficar com o 4B em vez de cair para o 2B.",
  "Runs on a cheap phone and still reads photographs. Short answers are good; long reasoning is where you'll notice the size.": "Roda em um celular barato e ainda lê fotografias. Respostas curtas saem bem; o tamanho aparece nos raciocínios longos.",
  "For a phone that can't hold anything else. Useful for tidying and shortening text; don't ask it to reason.": "Para um celular que não aguenta mais nada. Serve para organizar e encurtar textos; não peça que raciocine.",
  "This device is below what any local model needs": "Este dispositivo está abaixo do que qualquer modelo local exige",
  "Everything here runs on your own hardware, and the smallest useful model wants about 2 GB of memory to itself. Attune's tools that don't need a model still work.": "Tudo aqui roda no seu próprio hardware, e o menor modelo útil precisa de cerca de 2 GB de memória só para ele. As ferramentas do Attune que não usam modelo continuam funcionando.",
  "Neural Engine": "Neural Engine",
  "prefill + decode": "prefill + decode",
  "Rewrite": "Reescrever",
  "Field docs": "Documentos de campo",
  "It declined or dodged the question.": "Ele se recusou ou fugiu da pergunta.",
  "Say why you need it and what you'll do with it, and ask for the part it can answer.": "Diga por que precisa disso e o que fará com a resposta, e peça a parte que ele pode responder.",
  "It hedged instead of committing.": "Ele ficou em cima do muro em vez de se comprometer.",
  "Ask it to pick one and defend it: “Choose the single best option and say why the others lose.”": "Peça que escolha uma opção e a defenda: \"Escolha a melhor opção e diga por que as outras perdem.\"",
  "That's a generic answer — it could have been written without your details.": "Essa resposta é genérica — poderia ter sido escrita sem os seus detalhes.",
  "Give it your actual numbers and constraints, and ask it to redo the answer using only those.": "Passe seus números e limites reais e peça que refaça a resposta usando só eles.",
  "It spent the answer restating your question.": "Ele gastou a resposta repetindo a sua pergunta.",
  "Tell it to skip the recap and start at the answer.": "Mande pular o resumo e começar pela resposta.",
  "It looks cut off.": "Parece cortada.",
  "Ask it to continue from where it stopped, not to start again.": "Peça que continue de onde parou, em vez de recomeçar.",
  "It asked you a question instead of answering.": "Ele fez uma pergunta em vez de responder.",
  "Answer the question inside your next prompt so it can't stall again.": "Responda à pergunta dentro do seu próximo prompt, para ele não travar de novo.",
  "This repeats an earlier answer — the conversation is going in circles.": "Isso repete uma resposta anterior — a conversa está andando em círculos.",
  "Change the angle: ask for what it would do differently, or give it a constraint it hasn't had.": "Mude o ângulo: pergunte o que ele faria de diferente ou dê uma restrição que ele ainda não teve.",
  "Sharpen": "Afinar",
  "narrower and more specific — pin it down": "mais estreito e específico — delimite melhor",
  "Widen": "Ampliar",
  "step back and ask for options you haven't considered": "dê um passo atrás e peça opções em que você não pensou",
  "Press": "Pressionar",
  "challenge the answer and make it defend or correct itself": "conteste a resposta e faça-o defender ou corrigir",
  "Reads clean structure well — tags mark where context ends and the task begins.": "Lê bem estruturas limpas — as tags marcam onde o contexto termina e a tarefa começa.",
  "Turn on Extended Thinking for hard reasoning.": "Ative o Extended Thinking para raciocínios difíceis.",
  "Does best when you name the outcome and let it choose the path.": "Funciona melhor quando você diz o resultado e deixa que ele escolha o caminho.",
  "Let the router pick, or choose Thinking for complex tasks.": "Deixe o roteador escolher, ou escolha Thinking para tarefas complexas.",
  "Wants direct, concise input and defaults to short answers.": "Prefere entradas diretas e concisas e responde curto por padrão.",
  "Use Pro; enable Deep Research for multi-source work.": "Use o Pro; ative o Deep Research para trabalhos com várias fontes.",
  "Handles direct, conversational prompts; ask for reasoning explicitly.": "Lida bem com prompts diretos e conversacionais; peça o raciocínio de forma explícita.",
