  "3 templates · 5 history items": "3 modelos · 5 itens de histórico",
  "35B of knowledge, 3B doing the work on each token — near-frontier answers at a speed a laptop can sustain. A mixture-of-experts model keeps every expert in memory even though few run per token, so this needs the RAM of a 35B and the compute of a 3B.": "35B de conhecimento, 3B trabalhando a cada token — respostas quase de ponta, numa velocidade que um notebook sustenta. Um modelo de mistura de especialistas mantém todos os especialistas na memória, mesmo que poucos rodem por token; por isso precisa da RAM de um 35B e do processamento de um 3B.",
  "A bigger length budget for reports, plans and analysis.": "Um limite de tamanho maior para relatórios, planos e análises.",
  "Ask it as much as you like — no daily limit": "Pergunte o quanto quiser — sem limite diário",
