  "Small enough to download on mobile data if you need to.": "Pequeno o bastante para baixar com dados móveis, se precisar.",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "Este é um modelo grande para um celular. Ele roda, mas fica visivelmente mais lento quando o celular esquenta — mantenha as respostas curtas ou escolha o menor.",
  "Every tool, and all 31 country packs": "Todas as ferramentas e os 31 pacotes de países",
  "Finds what you promised people, from your own words": "Encontra o que você prometeu às pessoas, a partir das suas próprias palavras",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "Aleatoriedade fixa, para que um fluxo de trabalho dê a mesma saída toda vez que rodar.",
  "Free web search: DuckDuckGo, Bing and Mojeek at once, then the top pages are read in full, so answers come from real passages.": "Busca web grátis: DuckDuckGo, Bing e Mojeek ao mesmo tempo, e as melhores páginas são lidas por inteiro, para as respostas virem de trechos reais.",
  "Free · no key": "Grátis · sem chave",
  "Installing… {p}%": "Instalando… {p}%",
  "It remembers everything and can search it": "Lembra de tudo e pode pesquisar",
  "Learns your vocabulary and writes the way you do": "Aprende seu vocabulário e escreve do seu jeito",
  "No account, no sign-in, nothing uploaded": "Sem conta, sem login, nada enviado",
  "Running": "Rodando",
  "Loading the model…": "Carregando o modelo…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "Nada no app consegue acessar a internet — sem busca na web, sem mapas, sem downloads. O modelo e tudo no celular continuam funcionando.",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "O modelo raciocina primeiro em toda pergunta. Claramente melhor em problemas difíceis, mas no celular a resposta começa 30–90 s depois. Desligado: toque em \"Pensar\" só nas perguntas que precisam.",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "O mesmo modelo de baixo, com memória para guardar um livro inteiro de contexto de uma vez. Numa máquina de 48 GB, a RAM sobrando rende mais em contexto do que em precisão — você pode entregar um contrato inteiro ou um ano de anotações e ele mantém tudo à vista.",
  "The whole assistant, on your device": "O assistente completo, no seu dispositivo",
  "Works entirely offline. No account, ever.": "Funciona totalmente offline. Sem conta, nunca.",
  "Your API key": "Sua chave de API",
