  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "Os lembretes podem atrasar até 10 minutos. Toque para permitir \"Alarmes e lembretes\" para o Attune, para tocarem na hora certa.",
