  "Load weight confirmed (drawing, weighbridge or manufacturer) — not guessed": "Peso da carga confirmado (desenho, balança rodoviária ou fabricante) — não chutado",
  "Radius and boom length checked on the load chart for the exact configuration (counterweight, outrigger spread)": "Raio e comprimento da lança conferidos na tabela de carga para a configuração exata (contrapeso, abertura dos estabilizadores)",
