  "LMI / rated capacity limiter set for the actual configuration and tested": "LMI / limitador de capacidade ajustado para a configuração real e testado",
  "Wire ropes, hook, safety latch and sheaves in good condition": "Cabos de aço, gancho, trava de segurança e roldanas em bom estado",
