  "Send this report": "Enviar este relatório",
  "Not available in this build": "Indisponível nesta versão",
  "The phone is hot — it slows the processor down on purpose. Let it cool, take it out of its case, don't charge while asking.": "O celular está quente — ele reduz o processador de propósito. Deixe esfriar, tire da capinha e não carregue enquanto pergunta.",
  "Battery saver is on — it caps the processor. Turn it off while using Attune.": "A economia de bateria está ligada — ela limita o processador. Desligue enquanto usa o Attune.",
  "Free memory is low for this model — close other apps (games, camera, many browser tabs).": "A memória livre está baixa para este modelo — feche outros apps (jogos, câmera, muitas abas do navegador).",
  "The model is read from storage instead of RAM — update to the latest Attune APK (it loads the model into RAM).": "O modelo está sendo lido do armazenamento em vez da RAM — atualize para o APK mais recente do Attune (ele carrega o modelo na RAM).",
  "The engine is using its slowest processor path (no dotprod). Send this report.": "O motor está usando o caminho mais lento do processador (sem dotprod). Envie este relatório.",
  "The phone is critically hot — Attune stops an answer in progress and keeps what was written. Let it cool for a few minutes.": "O celular está quente demais — o Attune interrompe a resposta em andamento e guarda o que foi escrito. Deixe esfriar por alguns minutos.",
  "The phone is very hot — Attune waits up to 20 seconds before each new answer so it can cool, and uses fewer threads the next time the model starts.": "O celular está muito quente — o Attune espera até 20 segundos antes de cada nova resposta para esfriar e usa menos threads na próxima vez que o modelo iniciar.",
  "The phone is getting warm — long answers may slow down soon. Short breaks between answers keep it fast.": "O celular está esquentando — respostas longas podem ficar lentas em breve. Pequenas pausas entre as respostas o mantêm rápido.",
  "Only {n} threads are used for writing.": "Apenas {n} threads são usadas para escrever.",
  "This is a big model for a phone — Qwen 3.5 4B is about 2–3× faster.": "Este é um modelo grande para um celular — o Qwen 3.5 4B é cerca de 2–3× mais rápido.",
  "Nothing obvious — the phone may have slowed Attune while it was in the background. The new APK keeps it at full speed while writing.": "Nada óbvio — o celular pode ter reduzido o Attune enquanto ele estava em segundo plano. O novo APK o mantém em velocidade total ao escrever.",
  "Nothing is holding it back.": "Nada está atrapalhando.",
  "Money tools": "Ferramentas de dinheiro",
  "Gemma 4 E2B · fast engine (GPU)": "Gemma 4 E2B · motor rápido (GPU)",
  "Gemma 4 E4B · fast engine (GPU)": "Gemma 4 E4B · motor rápido (GPU)",
  "The fast one. Runs on the phone's graphics chip: the first words appear in under a second and it writes faster than you can read. Reads photos, English and Arabic. For hard reasoning, the E4B below is stronger.": "O rápido. Roda no chip gráfico do celular: as primeiras palavras aparecem em menos de um segundo e ele escreve mais rápido do que você lê. Lê fotos, inglês e árabe. Para raciocínio difícil, o E4B abaixo é mais forte.",
  "The stronger fast one: noticeably better answers than the E2B, still on the graphics chip — first words in about a second, then roughly 20–45 words a second on a flagship.": "O rápido mais forte: respostas visivelmente melhores que o E2B, ainda no chip gráfico — primeiras palavras em cerca de um segundo, depois uns 20–45 palavras por segundo em um topo de linha.",
  "Stronger ·": "Mais forte ·",
  "This model is large for this phone. It works, but answers come slowly and the phone gets warm. For quick answers use Gemma 4 E2B on the fast engine — reads photos, first words in about a second.": "Este modelo é grande para este celular. Funciona, mas as respostas saem devagar e o celular esquenta. Para respostas rápidas, use o Gemma 4 E2B no motor rápido — lê fotos, primeiras palavras em cerca de um segundo.",
  "Fast engine on the graphics chip": "Motor rápido no chip gráfico",
  "Fast engine on the CPU": "Motor rápido na CPU",
  "multi-token prediction on": "previsão de vários tokens ligada",
  "Use the graphics chip": "Usar o chip gráfico",
  "On: the model runs on the GPU — first words in about a second. Off: the CPU, slower, only for phones whose GPU driver misbehaves.": "Ligado: o modelo roda na GPU — primeiras palavras em cerca de um segundo. Desligado: a CPU, mais lenta, só para celulares cujo driver de GPU dá problema.",
  "Gemma 4 E2B on the graphics chip: first words in about a second, many times faster than this engine. {s} GB, once.": "Gemma 4 E2B no chip gráfico: primeiras palavras em cerca de um segundo, muitas vezes mais rápido que este motor. {s} GB, uma vez.",
  "The fast engine is running on the CPU, not the graphics chip — turn on “Use the graphics chip” above. If it switched itself off, the phone's GPU driver refused it: send this report.": "O motor rápido está rodando na CPU, não no chip gráfico — ligue \"Usar o chip gráfico\" acima. Se ele se desligou sozinho, o driver de GPU do celular o recusou: envie este relatório.",
  "The biggest speed-up on this phone is the fast engine: Gemma 4 E2B on the graphics chip — first words in about a second. Tap “Switch to the fast engine” above.": "O maior ganho de velocidade neste celular é o motor rápido: Gemma 4 E2B no chip gráfico — primeiras palavras em cerca de um segundo. Toque em \"Mudar para o motor rápido\" acima.",
  "The GPU would not start, so the fast engine is on the CPU. ": "A GPU não iniciou, então o motor rápido está na CPU. ",
  "Last time, starting the fast engine on the GPU closed the app. It is on the CPU now; you can try the GPU again in Engine → Speed.": "Da última vez, iniciar o motor rápido na GPU fechou o app. Agora ele está na CPU; você pode tentar a GPU de novo em Motor → Velocidade.",
  "Preparing the fast engine (the first start on the GPU takes longest)": "Preparando o motor rápido (a primeira inicialização na GPU demora mais)",
  "Change it… e.g. “also show the total in EGP”": "Mude... ex.: \"mostre também o total em EGP\"",
