  "Separate topics with an empty line. Only the paragraphs that fit the question are used, so this can be long.": "Separe os assuntos com uma linha em branco. Só os parágrafos que respondem à pergunta são usados, então pode ser longo.",
  "Facts": "Fatos",
  "It also runs this small program on your phone (offline, in a locked box — no internet, no files, no access to the app)": "Ele também roda este pequeno programa no seu celular (offline, numa caixa trancada — sem internet, sem arquivos, sem acesso ao app)",
  "Edit or improve my CV": "Editar ou melhorar meu currículo",
  "Say what to add or change («add my job at Dar Al Fouad Hospital as a nurse, 2019–2022», «change my phone to …»), or leave it empty and just make it more professional. You see the result before it is kept.": "Diga o que adicionar ou mudar («adicione meu emprego no Hospital Dar Al Fouad como enfermeiro, 2019–2022», «mude meu telefone para …»), ou deixe vazio e apenas deixe-o mais profissional. Você vê o resultado antes de ser guardado.",
