  "The model answered without any code — try asking again in other words.": "O modelo respondeu sem nenhum código — tente perguntar de novo com outras palavras.",
  "A picture — Studio draws it on this phone": "Uma imagem — o Studio desenha neste celular",
  "Another version": "Outra versão",
  "Could not open that picture": "Não foi possível abrir essa imagem",
  "Could not save": "Não foi possível salvar",
  "Current photo quality in 4 steps: people, places, products and text in pictures. Also edits a photo you give it (“make it night”, “remove the car”).": "Qualidade atual de foto em 4 passos: pessoas, lugares, produtos e texto em imagens. Também edita uma foto que você enviar (\"faça virar noite\", \"remova o carro\").",
  "Describe the picture, in Arabic or English — e.g. “a felucca on the Nile at sunset”": "Descreva a imagem, em árabe ou inglês — ex.: \"um felucca no Nilo ao pôr do sol\"",
  "Developing the picture…": "Revelando a imagem…",
  "Download it on Wi-Fi. After that, pictures are made with no internet at all.": "Baixe no Wi-Fi. Depois disso, as imagens são feitas sem nenhuma internet.",
  "Draw it": "Desenhar",
