  "Drawing on the GPU failed, so Attune switched Studio to the CPU. ": "O desenho na GPU falhou, então o Attune mudou o Studio para a CPU. ",
  "Drawing — step {n} of {t}": "Desenhando — passo {n} de {t}",
  "Each picture is made by a separate engine process: when it finishes, all its memory goes back to the phone. Nothing is uploaded.": "Cada imagem é feita por um processo de motor separado: quando termina, toda a memória volta ao celular. Nada é enviado.",
