  "The chat model was paused to make room, and is loading again.": "O modelo do chat foi pausado para liberar espaço e está carregando de novo.",
  "This APK has no picture engine yet — it comes with the next APK built on GitHub.": "Este APK ainda não tem motor de imagem — ele virá no próximo APK gerado no GitHub.",
  "This build draws on the CPU.": "Esta versão desenha na CPU.",
  "This build of the app has no picture engine yet.": "Esta versão do app ainda não tem motor de imagem.",
  "This phone has {n} GB — it may be too little for pictures.": "Este celular tem {n} GB — pode ser pouco para imagens.",
  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "Esta versão do Attune não tem motor de imagem no chip gráfico, então as imagens são desenhadas na CPU (mais lento). Uma atualização o adiciona.",
  "The picture engine stopped responding while loading the model, so it was stopped. Engine → Engine log shows its last lines — send them to support.": "O motor de imagem parou de responder ao carregar o modelo e foi interrompido. Motor → Registro do motor mostra suas últimas linhas — envie-as ao suporte.",
  "This phone's GPU driver did not answer, so pictures are drawn on the CPU (slower).": "O driver de GPU deste celular não respondeu, então as imagens são desenhadas na CPU (mais lento).",
  "What should change? e.g. “make it night, with the street lights on”": "O que deve mudar? ex.: \"deixe de noite, com os postes acesos\"",
  "Write a fuller description first (better pictures; uses the chat model)": "Escreva antes uma descrição mais completa (imagens melhores; usa o modelo do chat)",
