  "I couldn't make every test pass yet — here is the closest version; tap “Test & fix in Code” to keep going.": "Ainda não consegui fazer todos os testes passarem — aqui está a versão mais próxima; toque em \"Testar e corrigir em Código\" para continuar.",
  "Working it out as a program…": "Resolvendo como um programa…",
