  "FLUX.2 klein 4B · high quality": "FLUX.2 klein 4B · alta qualidade",
  "The best pictures this phone can make: the 8-bit build of FLUX.2 klein — finer detail, cleaner faces, hands and text. Also edits your photos by instruction.": "As melhores imagens que este celular consegue fazer: a versão de 8 bits do FLUX.2 klein — detalhes mais finos, rostos, mãos e texto mais limpos. Também edita suas fotos por instrução.",
  "That file is too large (15 MB at most)": "Esse arquivo é grande demais (15 MB no máximo)",
