  "Could not check it: {e}": "Não foi possível conferir: {e}",
  "Could not check it (no answer from the model).": "Não foi possível conferir (sem resposta do modelo).",
  "The phone's storage for Business is full — export a table to CSV and delete old records.": "O armazenamento de Negócios no celular está cheio — exporte uma tabela em CSV e apague registros antigos.",
  "Created — {n} tables": "Criado — {n} tabelas",
  "Deleted": "Excluído",
  "Your own ERP: customers, stock, jobs, invoices — whatever your business tracks. Change any table or column later, like Microsoft Access.": "Seu próprio ERP: clientes, estoque, serviços, faturas — o que o seu negócio controlar. Mude qualquer tabela ou coluna depois, como no Microsoft Access.",
  "{n} tables": "{n} tabelas",
  "Active": "Ativo",
  "Trial": "Teste",
  "The model didn't produce a usable design. Try again, describe it differently, or start from a template.": "O modelo não gerou um design utilizável. Tente de novo, descreva de outro jeito ou comece por um modelo pronto.",
  "This is the design. You can change every table and column after creating it.": "Este é o design. Você pode mudar cada tabela e coluna depois de criar.",
