  "e.g. We rent mobile cranes (20–500 t) with operators in Egypt. We track customers, jobs per site, daily rates, invoices and payments, maintenance and crew licences.": "Ex.: Alugamos guindastes móveis (20–500 t) com operadores no Egito. Controlamos clientes, serviços por obra, diárias, faturas e pagamentos, manutenção e habilitações da equipe.",
  "Designing your system…": "Projetando o seu sistema…",
  "Design it with AI": "Projetar com IA",
