  "Off by default: on some phones it doubles words and digits (“ItIt is is”, “20205”). Turn it on only if answers stay correct.": "Desligado por padrão: em alguns celulares ela duplica palavras e dígitos (\"ItIt is is\", \"20205\"). Ligue só se as respostas continuarem corretas.",
