  "Studio Turbo": "Studio Turbo",
  "Studio Pro": "Studio Pro",
  "Studio Pro HD": "Studio Pro HD",
  "Turbo · about 1 min": "Turbo · cerca de 1 min",
  "Studio Turbo+": "Studio Turbo+",
  "Recommended for your phone": "Recomendado para o seu celular",
  "Studio Ultra": "Studio Ultra",
  "Ultra · best quality, slow · {s} GB": "Ultra · melhor qualidade, lento · {s} GB",
  "best quality, slow": "melhor qualidade, lento",
  "fastest pictures": "imagens mais rápidas",
  "a graphics card with 8 GB or more: the most capable model": "uma placa de vídeo com 8 GB ou mais: o modelo mais capaz",
  "The most capable model: text inside pictures, busy scenes, people. Slow on a phone (about 10 minutes a picture), fast on a computer with a graphics card. Needs 12 GB RAM.": "O modelo mais capaz: texto dentro de imagens, cenas cheias, pessoas. Lento no celular (cerca de 10 minutos por imagem), rápido em computador com placa de vídeo. Precisa de 12 GB de RAM.",
  "about {s} s a picture": "cerca de {s} s por imagem",
  "8 GB or more and fast cores: the sharper XL model in one step": "8 GB ou mais e núcleos rápidos: o modelo XL, mais nítido, em um passo",
  "not enough free storage or speed for the XL model": "sem armazenamento livre ou velocidade suficiente para o modelo XL",
  "the fast model fits this phone's memory": "o modelo rápido cabe na memória deste celular",
  "little memory or slow cores: smaller pictures, still clear": "pouca memória ou núcleos lentos: imagens menores, ainda nítidas",
  "Turbo+ · about 20 s · {s} GB": "Turbo+ · cerca de 20 s · {s} GB",
  "Faster and sharper than Turbo, with a better match to what you ask for: about 20 seconds a picture on the CPU. 512 px. For phones with 8 GB RAM or more.": "Mais rápido e nítido que o Turbo, com melhor correspondência ao que você pede: cerca de 20 segundos por imagem na CPU. 512 px. Para celulares com 8 GB de RAM ou mais.",
  "Pro · best quality": "Pro · melhor qualidade",
  "Pro on this phone's CPU: 10–20 min a picture": "Pro na CPU deste celular: 10–20 min por imagem",
  "This phone's graphics chip isn't working with Studio, so the Pro model would take 10–20 minutes a picture on the CPU. Studio Turbo makes a picture in about a minute.": "O chip gráfico deste celular não está funcionando com o Studio, então o modelo Pro levaria 10–20 minutos por imagem na CPU. O Studio Turbo faz uma imagem em cerca de um minuto.",
  "Fast pictures on any phone: about a minute without a graphics chip, seconds with one. 512 px — great for ideas, drafts and posts.": "Imagens rápidas em qualquer celular: cerca de um minuto sem chip gráfico, segundos com um. 512 px — ótimo para ideias, rascunhos e posts.",
  "The best photo quality: people, places, products and text in pictures, 1024 px. Also edits a photo you give it (“make it night”, “remove the car”). Needs a working graphics chip — on the CPU a picture takes 10–20 minutes.": "A melhor qualidade de foto: pessoas, lugares, produtos e texto em imagens, 1024 px. Também edita uma foto que você enviar (\"faça virar noite\", \"remova o carro\"). Precisa de um chip gráfico funcionando — na CPU uma imagem leva 10–20 minutos.",
  "Studio Pro at full precision: finer detail, cleaner faces, hands and text. Also edits your photos by instruction. Needs a working graphics chip and 12 GB RAM.": "Studio Pro em precisão total: detalhes mais finos, rostos, mãos e texto mais limpos. Também edita suas fotos por instrução. Precisa de um chip gráfico funcionando e 12 GB de RAM.",
  "Still working — nothing is stuck. Turbo takes about 1–2 minutes on the CPU. Keep Attune open; Stop cancels it.": "Ainda trabalhando — nada travou. O Turbo leva cerca de 1–2 minutos na CPU. Mantenha o Attune aberto; Parar cancela.",
  "Still working — nothing is stuck. Without the graphics chip a Pro picture takes 10–20 minutes (edits take longer). For speed, pick Turbo. Keep Attune open; Stop cancels it.": "Ainda trabalhando — nada travou. Sem o chip gráfico, uma imagem Pro leva 10–20 minutos (edições demoram mais). Para ir mais rápido, escolha o Turbo. Mantenha o Attune aberto; Parar cancela.",
  "Delete this chat?": "Excluir esta conversa?",
  "This can't be undone.": "Isso não pode ser desfeito.",
  "Delete this reminder?": "Excluir este lembrete?",
  "Delete this project?": "Excluir este projeto?",
  "Remove this crane from the fleet?": "Remover este guindaste da frota?",
