  "Spark (helper)": "Spark (ajudante)",
  "Only works with Spark, Glow, Core and Zenith — not with the model in use.": "Só funciona com Spark, Glow, Core e Zenith — não com o modelo em uso.",
  "Download Spark as a helper (about 0.5 GB, once). Works with Glow, Core and Zenith.": "Baixe o Spark como ajudante (cerca de 0,5 GB, uma vez). Funciona com Glow, Core e Zenith.",
  "This is a big model for a phone — Core is about 2–3× faster.": "Este é um modelo grande para um celular — o Core é cerca de 2–3× mais rápido.",
  "The strongest model a 12 GB phone can run: expert answers, and the best at reading documents and photos.": "O modelo mais forte que um celular de 12 GB consegue rodar: respostas de especialista e o melhor em ler documentos e fotos.",
  "Core made 10% smaller for a 4 GB phone — worth it over Glow.": "O Core 10% menor para um celular de 4 GB — vale mais que o Glow.",
  "Runs on a budget phone and still reads photos. Good short answers; long reasoning shows its size.": "Roda em um celular simples e ainda lê fotos. Boas respostas curtas; raciocínios longos mostram o tamanho.",
  "For a phone that can't hold anything else: tidying and shortening text. Not for reasoning.": "Para um celular que não aguenta mais nada: organizar e encurtar textos. Não serve para raciocínio.",
  "The biggest speed-up on this phone is the fast engine: Blaze on the graphics chip — first words in about a second. Tap “Switch to the fast engine” above.": "O maior ganho de velocidade neste celular é o motor rápido: Blaze no chip gráfico — primeiras palavras em cerca de um segundo. Toque em \"Mudar para o motor rápido\" acima.",
