  "Put the ask after the data (Gemini/GPT guidance)": "Coloque o pedido depois dos dados (orientação Gemini/GPT)",
  "Define the output shape explicitly": "Defina explicitamente o formato da saída",
  "Name the goal so the model reasons toward it": "Nomeie o objetivo para o modelo raciocinar em direção a ele",
  "Specificity → fewer misinterpretations": "Especificidade → menos interpretações erradas",
  "Goal-framing beats tone adjectives alone": "Definir o objetivo vale mais que adjetivos de tom",
  "Data first, question last improves grounding": "Dados primeiro, pergunta por último melhora a fundamentação",
  "Role-free outcome framing (2026 guidance)": "Resultado sem papéis (orientação de 2026)",
  "Explicit output shape reduces rework": "Formato de saída explícito reduz retrabalho",
  "Goal + constraint framing produces usable scripts": "Objetivo + restrição geram roteiros utilizáveis",
  "Stated criteria prevent generic pro/con lists": "Critérios declarados evitam listas genéricas de prós e contras",
  "Concrete constraints beat generic advice": "Restrições concretas valem mais que conselhos genéricos",
  "Time constraints force actionable plans": "Restrições de tempo forçam planos acionáveis",
  "Matching to the posting outperforms templates": "Adaptar à vaga rende mais que modelos prontos",
  "Role-specific prompting beats generic question lists": "Prompts específicos para a função valem mais que listas genéricas de perguntas",
  "Source-anchored prompts reduce invented detail": "Prompts ancorados em fontes reduzem detalhes inventados",
  "Constraints up front prevent generic travel advice": "Restrições logo no início evitam conselhos de viagem genéricos",
  "Explaining the 'why' improves targeting (Anthropic)": "Explicar o \"porquê\" melhora o direcionamento (Anthropic)",
  "Search tools need source + recency constraints": "Ferramentas de busca precisam de restrições de fonte e de recência",
  "Constraints up front prevent generic answers": "Restrições logo no início evitam respostas genéricas",
  "Active recall outperforms re-reading": "A recuperação ativa rende mais que reler",
  "Sectioned output aids comprehension": "Saída em seções ajuda a compreensão",
  "Explicit critique requests beat 'what do you think'": "Pedir críticas explícitas vale mais que \"o que você acha\"",
  "Naming review axes prevents shallow feedback": "Nomear os eixos de revisão evita feedback superficial",
  "Include context + attempted fixes for accuracy": "Inclua contexto + tentativas de correção para mais precisão",
  "Section-by-section output beats 'write a page'": "Saída seção por seção vale mais que \"escreva uma página\"",
  "Persona-specific prompts improve targeting": "Prompts específicos para o perfil melhoram o direcionamento",
  "Stating criteria prevents generic pro/con lists": "Declarar critérios evita listas genéricas de prós e contras",
  "Level-setting improves explanation fit": "Definir o nível melhora a adequação da explicação",
  "Specifying length prevents rambling summaries": "Especificar o tamanho evita resumos longos demais",
  "Ask to implement, not 'suggest changes' (Anthropic)": "Peça para implementar, não para \"sugerir mudanças\" (Anthropic)",
  "Reasoning models excel with clear scope, no examples": "Modelos de raciocínio vão melhor com escopo claro e sem exemplos",
  "Name every state so nothing is left ambiguous": "Nomeie todos os estados para nada ficar ambíguo",
  "Natural language + explicit variety works on GPT": "Linguagem natural + variedade explícita funciona no GPT",
  "Outcome framing beats feature lists": "Definir o resultado vale mais que listas de recursos",
  "Gemini prefers direct, constrained prompts": "O Gemini prefere prompts diretos e delimitados",
  "Short + specific tone yields natural output": "Tom curto e específico gera texto natural",
  "Chain-of-thought: +~40% avg on hard reasoning (Wei et al.); MultiArith 18%→79%. Skip on reasoning models — minimal gain, more latency.": "Cadeia de raciocínio: +~40% em média em raciocínio difícil (Wei et al.); MultiArith 18%→79%. Dispense em modelos de raciocínio — ganho mínimo, mais latência.",
  "1–5 examples (few-shot) raise pattern-task accuracy up to +43%; best on non-reasoning models like Gemini. Don't add examples for pure reasoning tasks — can hurt.": "1–5 exemplos (few-shot) elevam a precisão em tarefas de padrões em até +43%; melhor em modelos que não raciocinam, como o Gemini. Não use exemplos em tarefas de puro raciocínio — pode atrapalhar.",
  "OpenAI/Anthropic 2026: describe what a good result looks like; over-instructing adds noise on modern models.": "OpenAI/Anthropic 2026: descreva como é um bom resultado; instruir demais gera ruído em modelos modernos.",
  "2026 practice: set how hard to think (thinking/effort control) and spend words on the outcome, not on 'think step by step'.": "Prática de 2026: defina o quanto pensar (controle de raciocínio/esforço) e gaste palavras no resultado, não em \"pense passo a passo\".",
  "Clarification-first reduces wasted turns — the model gathers missing context instead of guessing.": "Esclarecer primeiro reduz turnos perdidos — o modelo reúne o contexto que falta em vez de chutar.",
  "Outcome criteria (what 'good' means) outperform process instructions on 2026 models.": "Critérios de resultado (o que significa \"bom\") rendem mais que instruções de processo em modelos de 2026.",
  "Verification steps reduce errors on factual/analytical tasks.": "Passos de verificação reduzem erros em tarefas factuais e analíticas.",
  "Explicit sections prevent rambling updates": "Seções explícitas evitam atualizações prolixas",
  "Asking for risks surfaces what you forgot": "Pedir os riscos revela o que você esqueceu",
  "Outcome framing keeps feedback constructive": "Definir o resultado mantém o feedback construtivo",
  "Explicit audience prevents vague procedures": "Um público explícito evita procedimentos vagos",
  "Spaced repetition beats massed practice": "Repetição espaçada vence a prática concentrada",
  "Worked examples aid transfer to new problems": "Exemplos resolvidos ajudam a aplicar em problemas novos",
  "Planning prompts reduce rework on complex tasks": "Prompts de planejamento reduzem retrabalho em tarefas complexas",
  "Explicitly requesting edge cases improves coverage": "Pedir casos extremos explicitamente melhora a cobertura",
  "Specificity outperforms enthusiasm in cold outreach": "Especificidade rende mais que entusiasmo em contato frio",
  "Goal-anchored planning beats idea dumps": "Planejar ancorado no objetivo vale mais que despejo de ideias",
  "Requesting alternatives counters fixation": "Pedir alternativas combate a fixação",
  "Citation requirements reduce unsupported claims": "Exigir citações reduz afirmações sem base",
  "Grounding in supplied sources reduces hallucination; tell it to admit gaps.": "Basear-se nas fontes fornecidas reduz alucinações; mande admitir lacunas.",
