  "The GPU driver stalled twice while loading the picture model, so Attune switched Studio to the CPU (you can try the GPU again below).": "O driver da GPU travou duas vezes ao carregar o modelo de imagem, então o Attune mudou o Studio para a CPU (você pode tentar a GPU de novo abaixo).",
  "Show only the models worth using on this device": "Mostrar só os modelos que valem a pena neste dispositivo",
  "Combine your data": "Combinar seus dados",
