  "From the phone's Notebook app: open a note (or select several) → Share → Attune → “Save to Shelf”. Or pick exported files here: text, Word, PDF, web pages, Google Keep, Evernote, a .zip, or photos of notes.": "No app de notas do celular: abra uma nota (ou selecione várias) → Compartilhar → Attune → \"Salvar na Estante\". Ou escolha aqui arquivos exportados: texto, Word, PDF, páginas web, Google Keep, Evernote, um .zip ou fotos de notas.",
  "Versions & prices": "Versões e preços",
  "Pros & cons": "Prós e contras",
  "Compare with rivals": "Comparar com concorrentes",
