  "Those results were off-topic — searching another way…": "Esses resultados fugiram do assunto — pesquisando de outro jeito…",
  "Nothing found for that — try the area's name too (e.g. “… New Cairo”), or move the map there and search again.": "Nada encontrado para isso — tente também o nome da região (ex.: \"… Nova Cairo\") ou mova o mapa até lá e pesquise de novo.",
