  "Couldn't get your location — check that location is on.": "Não foi possível obter sua localização — confira se a localização está ligada.",
  "“{n}” isn't kept on this phone any more — pick the file again.": "\"{n}\" não está mais guardado neste celular — escolha o arquivo de novo.",
  "tap to continue": "toque para continuar",
  "The text and your questions are kept on this phone only. Forget removes them.": "O texto e suas perguntas ficam só neste celular. Esquecer os remove.",
  "Web · Auto": "Web · Auto",
  "Web: Auto — it searches only when a question needs fresh facts": "Web: Auto — só pesquisa quando a pergunta precisa de fatos recentes",
  "Pick the best model for each question": "Escolher o melhor modelo para cada pergunta",
  "Reading your {f} conversation…": "Lendo sua conversa com {f}…",
  "Reading the conversation…": "Lendo a conversa…",
  "Shared links are opened in the Android app — or paste the conversation's text here.": "Links compartilhados são abertos no app Android — ou cole aqui o texto da conversa.",
  "I read your conversation with {f}{t} (about {n} words). Ask me anything about it — check it, summarise it, or carry on from where it stopped.": "Li sua conversa com {f}{t} (cerca de {n} palavras). Pergunte qualquer coisa sobre ela — confira, resuma ou continue de onde parou.",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch it off with the Web button": "Attune · a IA roda no seu dispositivo · sem conta, sem login · busca na web só quando a pergunta precisa (Auto) — desligue no botão Web",
  "Web: Off — nothing is looked up": "Web: Desligada — nada é pesquisado",
  "While Web is off in Chat, questions about prices, specs, news, scores or this year are still looked up (only the search words leave the phone). Off: nothing is looked up unless you turn Web on.": "Com a Web desligada no Chat, perguntas sobre preços, especificações, notícias, placares ou este ano ainda são pesquisadas (só as palavras da busca saem do celular). Desligada: nada é pesquisado, a menos que você ligue a Web.",
  "The model wrote nonsense — restarting it in safe mode and asking again…": "O modelo escreveu bobagem — reiniciando em modo seguro e perguntando de novo…",
  "This model writes nonsense on this phone, even in safe mode. Pick another model in Engine (Core works well) and tell us which one failed.": "Este modelo escreve bobagem neste celular, mesmo em modo seguro. Escolha outro modelo em Motor (o Core funciona bem) e nos diga qual falhou.",
  "Safe mode is on for this model: it once wrote nonsense on this phone, so it runs without speed tricks and with full-precision memory (a little slower, same answers).": "O modo seguro está ligado para este modelo: ele já escreveu bobagem neste celular, então roda sem truques de velocidade e com memória de precisão total (um pouco mais lento, mesmas respostas).",
  "Turn safe mode off": "Desligar o modo seguro",
