  "per passenger": "por passageiro",
  "Ask the airline for the reason: weather or an air-traffic strike would cancel it; a technical fault or crew shortage would not.": "Pergunte à companhia aérea o motivo: mau tempo ou greve do controle aéreo anulam o direito; falha técnica ou falta de tripulação, não.",
  "Write the claim": "Escrever a reclamação",
  "No compensation": "Sem indenização",
  "Worked out from the published rules (EU 261, UK 261, Canada's APPR). Airlines sometimes refuse at first — a polite second letter or the national enforcement body usually settles it.": "Calculado a partir das regras publicadas (EU 261, UK 261, APPR do Canadá). As companhias às vezes recusam no início — uma segunda carta educada ou o órgão nacional de fiscalização costuma resolver.",
