  "Was the airline a European one? (EU rules cover flights INTO Europe only on European airlines)": "A companhia aérea era europeia? (As regras da UE cobrem voos PARA a Europa só em companhias europeias)",
  "Was the airline a UK one? (UK rules cover flights INTO the UK only on UK airlines)": "A companhia aérea era do Reino Unido? (As regras do Reino Unido cobrem voos PARA o Reino Unido só em companhias britânicas)",
  "Which airline was it? (Canada's amounts depend on its size)": "Qual era a companhia aérea? (Os valores do Canadá dependem do porte dela)",
  "How late did you arrive at your destination (hours)?": "Com quantas horas de atraso você chegou ao destino?",
  "Over 3,500 km with a 3–4 hour delay: the airline may halve it.": "Mais de 3.500 km com atraso de 3–4 horas: a companhia pode pagar a metade.",
  "Told 7–13 days ahead: not owed if they offered a flight leaving at most 2 h earlier and arriving at most 4 h later than yours.": "Avisado de 7 a 13 dias antes: sem direito se ofereceram um voo saindo no máximo 2 h antes e chegando no máximo 4 h depois do seu.",
  "Told under 7 days ahead: not owed only if they offered a flight leaving at most 1 h earlier and arriving at most 2 h later than yours.": "Avisado menos de 7 dias antes: sem direito só se ofereceram um voo saindo no máximo 1 h antes e chegando no máximo 2 h depois do seu.",
  "Owed when the delay was within the airline's control and not for safety. Claim within 1 year.": "Devido quando o atraso estava sob controle da companhia e não foi por segurança. Reclame em até 1 ano.",
