  "Running on the NPU ({d}).": "Rodando na NPU ({d}).",
  "Runs the model on the Snapdragon NPU (Hexagon): much cooler, often faster at reading. Works best with Core Max (8-bit). Switches itself back to the CPU if anything goes wrong.": "Roda o modelo na NPU Snapdragon (Hexagon): bem mais fria, muitas vezes mais rápida para ler. Funciona melhor com Core Max (8 bits). Volta sozinha para a CPU se algo der errado.",
