  "Last time, starting on the NPU closed the app. Attune is back on the CPU; you can try it again in Engine → Speed.": "Da última vez, iniciar na NPU fechou o app. O Attune voltou para a CPU; você pode tentar de novo em Motor → Velocidade.",
  "You have {b}. Until {d} ({n} days) these are due: {t}. What is left, shared over the days, is what you can spend each day.": "Você tem {b}. Até {d} ({n} dias) vencem: {t}. O que sobra, dividido pelos dias, é o que você pode gastar por dia.",
