  "No missions yet. Start one above — a saving goal, a weight goal, something to buy, a spending limit, a debt or a course.": "Nenhuma missão ainda. Comece uma acima — uma meta de economia, de peso, algo para comprar, um limite de gastos, uma dívida ou um curso.",
