  "Keep your phone and computer (or two phones) the same. The data is locked before it leaves this device; what you delete on one is deleted on the other, nothing else is lost.": "Mantenha seu celular e computador (ou dois celulares) iguais. Os dados são bloqueados antes de sair deste aparelho; o que você excluir em um é excluído no outro, nada mais se perde.",
  "Wi-Fi": "Wi-Fi",
  "Google Drive": "Google Drive",
  "Allow Attune to find your other device on this Wi-Fi (Android asks once).": "Permita que o Attune encontre seu outro aparelho neste Wi-Fi (o Android pergunta uma vez).",
  "On the other device: Backup → Sync → Wi-Fi → Connect, and type:": "No outro aparelho: Backup → Sincronizar → Wi-Fi → Conectar, e digite:",
  "not on Wi-Fi": "fora do Wi-Fi",
  "Show a code on this device": "Mostrar um código neste aparelho",
  "Or connect to the other device": "Ou conecte-se ao outro aparelho",
  "Make this device exactly like the other one (removes what the other doesn't have)": "Deixar este aparelho exatamente igual ao outro (remove o que o outro não tem)",
  "Connect and sync": "Conectar e sincronizar",
  "One file in your own Google Drive, in a hidden folder only Attune can open. It is locked with your sync passphrase on this device, so Google only stores noise.": "Um arquivo no seu próprio Google Drive, numa pasta oculta que só o Attune abre. Ele é bloqueado com sua senha de sincronização neste aparelho, então o Google só guarda ruído.",
  "Sync passphrase set on this device.": "Senha de sincronização definida neste aparelho.",
  "Sync passphrase (10+ characters, the same on every device)": "Senha de sincronização (10+ caracteres, a mesma em todos os aparelhos)",
  "Save passphrase": "Salvar senha",
  "Sync with Google Drive": "Sincronizar com o Google Drive",
  "Last synced: {d}": "Última sincronização: {d}",
  "Wrong code or passphrase — nothing was changed.": "Código ou senha errados — nada foi alterado.",
  "Use at least 10 characters — the file lives in your Drive, so the passphrase is its only lock.": "Use pelo menos 10 caracteres — o arquivo fica no seu Drive, então a senha é a única tranca dele.",
  "That passphrase is too easy to guess.": "Essa senha é fácil demais de adivinhar.",
  "Only available in the Attune app": "Disponível só no app Attune",
  "Google sync on the computer comes in the next update — use Wi-Fi with your phone for now.": "A sincronização com o Google no computador chega na próxima atualização — por enquanto, use o Wi-Fi com seu celular.",
