  "Connections: {n} · places: {p} · blocked: {b}. Each place and why is below.": "Conexões: {n} · lugares: {p} · bloqueadas: {b}. Cada lugar e o motivo estão abaixo.",
  "No connections at all — Attune worked fully offline.": "Nenhuma conexão — o Attune funcionou totalmente offline.",
  "The AI ran on this device: none of your chats, notes, photos or money went to an AI company.": "A IA rodou neste aparelho: nenhuma conversa, nota, foto ou dado financeiro seu foi para uma empresa de IA.",
  "{n} times": "{n} vezes",
