  "Only the place and the reason are kept, never what was sent. Counted on this device; it starts from the day you installed this update.": "Só o lugar e o motivo são guardados, nunca o que foi enviado. Contado neste aparelho; começa no dia em que você instalou esta atualização.",
  "page request": "pedido de página",
