  "Going out: {a}": "Saindo: {a}",
  "Coming in: {a}": "Entrando: {a}",
  "Nothing coming up. Add a reminder, a date (a trial, a renewal, a warranty), a payment with someone, or X-ray a chat — it all shows here.": "Nada por vir. Adicione um lembrete, uma data (um teste grátis, uma renovação, uma garantia), um pagamento com alguém, ou faça o raio-X de uma conversa — tudo aparece aqui.",
  "You pay": "Você paga",
  "Comes in": "Entra",
  "Only a reminder — nothing happens by itself if you skip it.": "Só um lembrete — nada acontece sozinho se você ignorar.",
  "The free trial turns into a paid plan: {amount}.": "O teste grátis vira um plano pago: {amount}.",
  "The free trial turns into a paid plan.": "O teste grátis vira um plano pago.",
  "It renews and charges {amount} again.": "Renova e cobra {amount} de novo.",
  "It renews and charges you again.": "Renova e cobra você de novo.",
  "The last day to return it — after this you keep it.": "O último dia para devolver — depois disso fica com você.",
  "The warranty ends — a repair after this is on you.": "A garantia acaba — um conserto depois disso é por sua conta.",
  "It expires — renewing late can cost a fine or a trip.": "Vence — renovar atrasado pode custar multa ou uma ida ao local.",
  "The date passes.": "A data passa.",
