  "{amount} should come in — ask if it doesn't.": "{amount} deve entrar — cobre se não vier.",
  "You pay {who} {amount} — late, and trust drops.": "Você paga {amount} a {who} — atrasar diminui a confiança.",
  "{amount} to pay — late fees or a cut service.": "{amount} a pagar — multa por atraso ou serviço cortado.",
  "{amount} goes out of your money — keep it there.": "{amount} sai do seu dinheiro — deixe reservado.",
  "{who} owes you {amount} — remind them, or it gets forgotten.": "{who} te deve {amount} — lembre a pessoa, senão é esquecido.",
  "You owe {who} {amount} — paying late costs trust.": "Você deve {amount} a {who} — pagar atrasado custa confiança.",
  "{who} promised this — follow up, or it slips.": "{who} prometeu isto — cobre, senão escapa.",
  "Paint over the person or thing to remove, then tap Remove.": "Pinte por cima da pessoa ou coisa a remover e toque em Remover.",
  "Brush": "Pincel",
