  "Removed in {t}": "Removido em {t}",
  "Removes people and things you paint over, in about a second, on the phone.": "Remove pessoas e coisas que você pintar, em cerca de um segundo, no celular.",
  "eraser model": "modelo borracha",
  "Download the eraser first (28 MB, once).": "Baixe a borracha primeiro (28 MB, uma vez).",
  "The photo is too big for the eraser — try a smaller one": "A foto é grande demais para a borracha — tente uma menor",
  "The eraser failed": "A borracha falhou",
  "That picture is gone.": "Essa imagem não existe mais.",
  "Couldn't open that photo.": "Não foi possível abrir essa foto.",
  "Log food on {n} more days and your target will follow what your body really does.": "Registre a comida em mais {n} dias e sua meta vai seguir o que seu corpo realmente faz.",
  "Weigh yourself 2–3 times a week for two weeks and your target will follow what your body really does.": "Pese-se 2–3 vezes por semana durante duas semanas e sua meta vai seguir o que seu corpo realmente faz.",
  "You ate about {eaten} kcal a day and your weight held — so you burn about {burn}. Your plan now counts {tdee}.": "Você comeu cerca de {eaten} kcal por dia e seu peso se manteve — então você gasta cerca de {burn}. Seu plano agora conta {tdee}.",
  "You ate about {eaten} kcal a day and lost {kg} kg a week — so you burn about {burn}. Your plan now counts {tdee}.": "Você comeu cerca de {eaten} kcal por dia e perdeu {kg} kg por semana — então você gasta cerca de {burn}. Seu plano agora conta {tdee}.",
  "You ate about {eaten} kcal a day and gained {kg} kg a week — so you burn about {burn}. Your plan now counts {tdee}.": "Você comeu cerca de {eaten} kcal por dia e ganhou {kg} kg por semana — então você gasta cerca de {burn}. Seu plano agora conta {tdee}.",
  "Remembered about {p}": "Lembrado sobre {p}",
  "Project brain": "Cérebro do projeto",
  "As you chat in this project, what you decide, what is still open and the dates coming up collect here — and the assistant keeps to them.": "Enquanto você conversa neste projeto, o que você decide, o que ainda está aberto e as próximas datas se juntam aqui — e o assistente segue isso.",
  "Decided": "Decidido",
  "Still open": "Ainda aberto",
  "Test a big decision": "Testar uma grande decisão",
  "Cash or installments, a new flat, a second car — see 2,000 futures from your own money before you decide.": "À vista ou parcelado, um apartamento novo, um segundo carro — veja 2.000 futuros com o seu próprio dinheiro antes de decidir.",
  "Option name": "Nome da opção",
  "Pay now": "Pagar agora",
