  "Inflation": "Inflação",
  "Bank certificate": "Certificado bancário",
  "Run the futures": "Rodar os futuros",
  "The simulator needs at least a month of your income and spending in Money.": "O simulador precisa de pelo menos um mês da sua receita e dos seus gastos em Dinheiro.",
  "Option": "Opção",
  "Never runs out": "Nunca acaba",
