  "Owned after 5 years": "Seu depois de 5 anos",
  "Don't do it": "Não faça",
  "Stress tests: chance cash never runs out": "Testes de estresse: chance de o dinheiro nunca acabar",
  "Median of 2,000 futures in today's {c}, from your last {d} days in Money. Installments are fixed, so inflation makes them smaller each month; savings earn the certificate rate. A model, not a promise.": "Mediana de 2.000 futuros em {c} de hoje, a partir dos seus últimos {d} dias em Dinheiro. As parcelas são fixas, então a inflação as diminui a cada mês; a poupança rende a taxa do certificado. Um modelo, não uma promessa.",
  "Careful: with every option, your cash runs out in more than 1 future in 10. The safest is {best} ({ok}% of futures stay above zero).": "Cuidado: com qualquer opção, seu dinheiro acaba em mais de 1 futuro em 10. A mais segura é {best} ({ok}% dos futuros ficam acima de zero).",
  "{best}: {ok}% of futures never run out of cash; after 5 years you would have about {worth} (today's pounds, including what you bought).": "{best}: em {ok}% dos futuros o dinheiro nunca acaba; depois de 5 anos você teria cerca de {worth} (em libras de hoje, incluindo o que comprou).",
  "{best} is better: {ok}% of futures never run out of cash, and after 5 years you would have about {worth} in today's pounds — {diff} more than {other}.": "{best} é melhor: em {ok}% dos futuros o dinheiro nunca acaba, e depois de 5 anos você teria cerca de {worth} em libras de hoje — {diff} a mais que {other}.",
  "The answer came in English — writing it again in Arabic…": "A resposta veio em inglês — escrevendo de novo em árabe…",
  "The answer came in the wrong language — writing it again in English…": "A resposta veio no idioma errado — escrevendo de novo em inglês…",
  "{n} calculations checked by code — all correct": "{n} cálculos verificados por código — todos corretos",
  "Checked by code: {n} calculation(s) don't add up": "Verificado por código: {n} cálculo(s) não batem",
  "not": "não",
  "Copy all": "Copiar tudo",
  "not published": "não publicado",
  "Message alerts": "Alertas de mensagem",
  "Tell Attune whose message you are waiting for — on WhatsApp, Gmail or any email app — and it tells you the moment it arrives. Checked on this phone; SMS only if you switch it on below.": "Diga ao Attune de quem você espera mensagem — no WhatsApp, Gmail ou qualquer app de e-mail — e ele avisa assim que chegar. Verificado neste celular; SMS só se você ativar abaixo.",
  "Turn on Notification access for Attune so it can see new messages (Settings opens). If it is grey, see “restricted setting” in Money → Payments.": "Ative o Acesso a notificações para o Attune ver novas mensagens (as Configurações abrem). Se estiver cinza, veja “configuração restrita” em Dinheiro → Pagamentos.",
  "e.g. tell me when Ahmed messages me": "ex.: me avise quando o Ahmed me mandar mensagem",
