  "Make the lift plan (PDF)": "Gerar o plano de içamento (PDF)",
  "Set prices first — the catalogue lists items with a price": "Defina os preços primeiro — o catálogo lista itens com preço",
  "Your items, prices and what is in stock — as a WhatsApp message or a PDF, with an Order button that opens WhatsApp.": "Seus itens, preços e o que tem em estoque — como mensagem de WhatsApp ou PDF, com um botão Pedir que abre o WhatsApp.",
  "Prices or stock changed since you shared it — share the new one.": "Preços ou estoque mudaram desde que você compartilhou — compartilhe o novo.",
