  "Recall": "Recordar",
  "Find anything on your phone by meaning — screenshots, notifications, chats, notes": "Encontre qualquer coisa no celular pelo sentido — capturas de tela, notificações, conversas, notas",
  "Reading {a} of {b}…": "Lendo {a} de {b}…",
  "{n} added — text read in {k}": "{n} adicionados — texto lido em {k}",
  "Turn on Notification access for Attune, then come back": "Ative o Acesso a notificações para o Attune e volte aqui",
  "Kept notifications forgotten": "Notificações guardadas esquecidas",
  "Find anything… e.g. the wifi password from a screenshot, the address Ahmed sent": "Encontre qualquer coisa… ex.: a senha do wifi de uma captura de tela, o endereço que o Ahmed mandou",
  "Looking in": "Procurando em",
  "Nothing found — try other words, or fewer": "Nada encontrado — tente outras palavras, ou menos",
  "Android said no — you can allow SMS for Attune in App info.": "O Android recusou — você pode permitir SMS para o Attune em Informações do app.",
  "{n} bank messages from the last year are waiting below for you to check.": "{n} mensagens do banco do último ano esperam abaixo para você conferir.",
  "Bring in your old bank SMS": "Trazer seus SMS antigos do banco",
  "Money starts with the last 12 months instead of today. Only bank and wallet messages; never one-time codes; nothing leaves the phone.": "O Dinheiro começa com os últimos 12 meses em vez de hoje. Só mensagens de bancos e carteiras; nunca códigos de uso único; nada sai do celular.",
  "Read my bank SMS": "Ler meus SMS do banco",
  "{n} emails about money read — {p} payments are waiting in Money for a tap.": "{n} e-mails sobre dinheiro lidos — {p} pagamentos esperam em Dinheiro por um toque.",
  "Gmail is connected": "O Gmail está conectado",
  "Read my Gmail by itself": "Ler meu Gmail sozinho",
  "Once a day Attune reads the new emails about money — receipts, bank alerts, subscriptions, price changes. Last read: {t}. {n} kept for Recall.": "Uma vez por dia o Attune lê os novos e-mails sobre dinheiro — recibos, alertas do banco, assinaturas, mudanças de preço. Última leitura: {t}. {n} guardados para Recordar.",
  "Receipts, bank alerts, subscriptions and price changes go to Money, the Overpaying check and Recall. Read on this phone; never one-time codes. Google asks you once.": "Recibos, alertas do banco, assinaturas e mudanças de preço vão para Dinheiro, a Checagem de preço alto e Recordar. Lido neste celular; nunca códigos de uso único. O Google pergunta uma vez.",
  "Connect Gmail": "Conectar Gmail",
  "Disconnect": "Desconectar",
  "{n} payments from Gmail are waiting in Money": "{n} pagamentos do Gmail esperam em Dinheiro",
  "Gmail isn't connected yet": "O Gmail ainda não está conectado",
  "Gmail sign-in was cancelled": "O login no Gmail foi cancelado",
  "Google asks you to confirm again — tap Read now.": "O Google pede para confirmar de novo — toque em Ler agora.",
  "Attune only reads emails about money, on this phone. They never go to Attune, to an AI in the cloud or to anyone else, and are never used for ads. Disconnect any time.": "O Attune só lê e-mails sobre dinheiro, neste celular. Eles nunca vão para o Attune, para uma IA na nuvem nem para mais ninguém, e nunca são usados para anúncios. Desconecte quando quiser.",
  "Who should it go to? Add an email address.": "Para quem vai? Adicione um endereço de e-mail.",
  "You can still use Open in Gmail.": "Você ainda pode usar Abrir no Gmail.",
  "Sent from your Gmail to {to}.": "Enviado do seu Gmail para {to}.",
  "Your email — check it, then send": "Seu e-mail — confira e depois envie",
  "{n}'s email address": "Endereço de e-mail de {n}",
  "Not an email address: {a}": "Não é um endereço de e-mail: {a}",
  "Subject": "Assunto",
  "Writing it…": "Escrevendo…",
  "Open in Gmail": "Abrir no Gmail",
  "Nothing is sent until you tap Send — here or in Gmail.": "Nada é enviado até você tocar em Enviar — aqui ou no Gmail.",
  "No email app on this phone — copy the email instead.": "Nenhum app de e-mail neste celular — copie o e-mail.",
  "Keep my messages and notifications forever": "Guardar minhas mensagens e notificações para sempre",
  "WhatsApp, SMS, email, deliveries, banks — so you can find what someone sent, years later. Never one-time codes. Backed up with Attune's backup (Backup & restore).": "WhatsApp, SMS, e-mail, entregas, bancos — para você achar o que alguém mandou, anos depois. Nunca códigos de uso único. Incluído no backup do Attune (Backup e restauração).",
  "{n} kept.": "{n} guardadas.",
  "New notifications are not kept now — the ones kept stay": "Novas notificações não são mais guardadas — as já guardadas ficam",
