  "Like WhatsApp: pick a folder once — on this phone (offline) or in Google Drive (online) — and Attune saves a locked backup there every day, messages included.": "Como no WhatsApp: escolha uma pasta uma vez — neste celular (offline) ou no Google Drive (online) — e o Attune salva lá um backup bloqueado todo dia, com as mensagens.",
