  "Their text is read on the phone, so “the receipt from Carrefour” finds them. They are kept in Mind.": "O texto delas é lido no celular, então “o recibo do Carrefour” as encontra. Elas ficam guardadas em Mente.",
  "Keep my notifications for 30 days": "Guardar minhas notificações por 30 dias",
