  "Talk to Attune": "Falar com o Attune",
  "Your details — bookings and better answers": "Seus dados — reservas e respostas melhores",
  "Private: everything here stays on this phone — Attune never uploads it, and its AI runs on the phone. Answers and agents use only your trip and daily-life details (never your passport, phone or email). A booking site gets your name, passport and phone only when you tap “Fill my details”.": "Privado: tudo aqui fica apenas neste celular — o Attune nunca envia para a nuvem e a IA roda no próprio aparelho. As respostas e os agentes usam apenas seus detalhes de viagem e rotina (nunca seu passaporte, telefone ou e-mail). Um site de reservas só recebe seu nome, passaporte e telefone quando você toca em “Preencher meus dados”.",
  "Use my details to make answers and agents fit me": "Usar meus dados para personalizar respostas e agentes",
  "Trips and hotels": "Viagens e hotéis",
  "Agents use these when your sentence doesn't say — e.g. a hotel watch looks for your stars by itself.": "Os agentes usam esses dados quando sua frase não especifica — ex.: um alerta de hotel já busca a sua categoria de estrelas automaticamente.",
  "Daily life": "Rotina diária",
  "So Chat's answers fit you: food, health, your car, your work.": "Para que as respostas da Conversa combinem com você: alimentação, saúde, seu carro, seu trabalho.",
  "For booking forms": "Para formulários de reserva",
  "Typed into a booking site only when you tap “Fill my details”. Never used in answers.": "Digitado em um site de reservas somente quando você toca em “Preencher meus dados”. Nunca é usado nas respostas.",
