  "With more than one model installed: quick questions use the one already running; code, maths, reasoning and long reports move to your strongest model that runs smoothly here, and photos to one that sees. A switch takes 10–30 s.": "Com mais de um modelo instalado: perguntas rápidas usam o que já está aberto; código, matemática, raciocínio e relatórios longos mudam para o modelo mais forte que roda bem aqui, e fotos usam um modelo com visão. A troca leva de 10 a 30 s.",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \\\"nothing leaves this phone\\\".": "O modelo em si nunca usa a rede. O registro mostra cada conexão que o app fez ou recusou, apenas com servidor e motivo — a prova por trás de \"nada sai deste celular\".",
