  "the repayment schedule": "o cronograma de pagamento",
  "what exactly will be delivered": "o que exatamente será entregue",
  "the price and when it is paid": "o preço e quando será pago",
  "the deadline": "o prazo final",
  "Ask for a normal deposit or a bank guarantee instead, and never sign anything blank.": "Peça uma caução normal ou garantia bancária em vez disso, e nunca assine nada em branco.",
  "It renews by itself — you keep paying unless you cancel in time.": "Renova-se automaticamente — você continua pagando a menos que cancele a tempo.",
  "Ask for renewal only by written agreement, or put the cancel-by date in your Deadline Radar.": "Peça que a renovação dependa de acordo por escrito ou anote a data limite de cancelamento no seu Radar de prazos.",
  "Only one side can end it, or it can be ended without notice.": "Apenas um dos lados pode rescindir, ou o contrato pode ser encerrado sem aviso prévio.",
  "Ask that both sides can end it, with the same written notice (e.g. 30 days).": "Peça que ambos os lados possam rescindir com o mesmo aviso prévio por escrito (ex.: 30 dias).",
  "The other side can change the terms or the price on its own.": "A outra parte pode alterar as condições ou o preço sozinha.",
  "Ask that changes need both signatures, and that you can leave without a penalty if you don't accept them.": "Peça que qualquer alteração exija a assinatura de ambos e que você possa sair sem multa caso não concorde.",
  "A penalty or forfeit clause — check the amount and that it applies to both sides.": "Cláusula de multa ou perda de valores — confira o valor e se vale igualmente para os dois lados.",
  "Ask for a cap (e.g. one month's value) and the same penalty for the other side.": "Peça um teto (ex.: o valor de um mês) e a mesma multa para o outro lado.",
  "Money you pay here does not come back, even if the deal falls through.": "O dinheiro pago aqui não é devolvido, mesmo que o negócio não se concretize.",
  "Ask that it is refunded if the other side cancels or doesn't deliver.": "Peça o reembolso integral caso a outra parte cancele ou não entregue.",
  "You carry all the risk, with no limit.": "Você assume todo o risco, sem limite.",
  "Ask for a limit (e.g. the contract's value) and to exclude what you can't control.": "Peça um limite de responsabilidade (ex.: o valor do contrato) e a exclusão do que estiver fora do seu controle.",
  "You may not work for a competitor after you leave — check how long and where.": "Você fica proibido de trabalhar para concorrentes após sair — confira por quanto tempo e em qual região.",
  "Ask for 6–12 months at most, one city or field, and pay for the time it applies.": "Peça no máximo 6 a 12 meses, restrito a uma cidade ou área de atuação, e remuneração durante o período de restrição.",
  "Everything you make — even in your own time — would belong to them.": "Tudo o que você criar — mesmo no seu tempo livre — passaria a pertencer a eles.",
  "Ask to limit it to work done for them, in work time, with their tools.": "Peça para limitar apenas ao trabalho feito para eles, no horário de expediente e usando as ferramentas deles.",
  "Disputes go to arbitration or to another country's courts — this can be slow and expensive for you.": "Disputas vão para arbitragem ou tribunais de outro país — isso pode ser lento e caro para você.",
  "Ask for the courts of your own city.": "Peça o foro dos tribunais da sua própria cidade.",
  "You give up a right (to sue, to a refund, to object).": "Você abre mão de um direito (de processar, pedir reembolso ou contestar).",
  "Ask to delete the waiver.": "Peça a exclusão dessa cláusula de renúncia.",
  "Sold as it is, with no guarantee — problems found later are yours.": "Vendido no estado em que se encontra, sem garantia — defeitos descobertos depois ficam por sua conta.",
  "Inspect it first (with an expert), or ask for a written guarantee period.": "Faça uma vistoria antes (com um especialista) ou peça um prazo de garantia por escrito.",
  "Secrecy that never ends.": "Confidencialidade sem prazo para acabar.",
  "Ask for a fixed number of years (2–5 is common).": "Peça um número fixo de anos (2 a 5 anos é o padrão).",
  "They may take money from your salary — check when and how much.": "Eles podem descontar valores do seu salário — confira quando e quanto.",
  "Ask that deductions are only for set reasons, with a written notice and a cap.": "Peça que descontos só ocorram por motivos claros, com aviso por escrito e limite máximo.",
  "Ask for no more than about 1–2 % a month, and a few days' grace.": "Peça no máximo 1 a 2 % ao mês e alguns dias de tolerância.",
  "Ask for 5–10 % a year, written as a fixed schedule.": "Peça reajuste de 5 a 10 % ao ano, definido em tabela fixa.",
  "Ask for 3 months.": "Peça 3 meses.",
