  "US Navy method: waist at the navel (women: narrowest), neck below the Adam's apple — ±3 %. The trend matters more than one number.": "Método da Marinha dos EUA: cintura na altura do umbigo (mulheres: parte mais fina), pescoço abaixo do pomo de Adão — ±3 %. A tendência importa mais do que um número isolado.",
